                        IF (ICC_LO>0) THEN; X_LO=M2%CUT_CELL(ICC_LO)%XYZCEN(IAXIS,1); ELSE; X_LO=M2%XC(IIO-1); ENDIF
                        IF (ICC_HI>0) THEN; X_HI=M2%CUT_CELL(ICC_HI)%XYZCEN(IAXIS,1); ELSE; X_HI=M2%XC(IIO); ENDIF
                        IDX = 1._EB/(X_HI - X_LO)
